-- =============================================================================
-- Origen Salud · Propuesta LOCAL · Relaciones cruzadas CDT 2025
-- dentar-cdt-relaciones-propuerto.sql
-- =============================================================================
-- NO EJECUTADO. Los 15 tipos se conservan literalmente desde la fuente CDT.
-- Ejecutar después de cargar DENTAR-PR y sus identificadores CDT-2025.
-- Requiere autorización explícita para DDL/carga y validación en entorno controlado.
-- =============================================================================
SET client_encoding = 'UTF8';

BEGIN;

-- 1. Sistemas terminológicos necesarios para que las relaciones sean navegables.
-- El bootstrap cargó esta tabla con ids explícitos (1..4) sin avanzar el SERIAL,
-- por lo que un INSERT sin id choca con la PK. Se alinea la secuencia primero.
SELECT setval(
    pg_get_serial_sequence('os_terminology_system', 'id'),
    (SELECT COALESCE(max(id), 1) FROM os_terminology_system),
    true
);

ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, uri = EXCLUDED.uri;

-- 2. Alias consistente del Nomenclador: el engine histórico usa NOMENCLADOR_AR
--    y el núcleo editorial usa NOMENCLADOR-AR. Conservar el valor original.
SELECT item_id, 'NOMENCLADOR-AR', value, is_primary
  FROM os_catalog_identifier
 WHERE system_name = 'NOMENCLADOR_AR'
ON CONFLICT (item_id, system_name, value) DO NOTHING;

-- 3. Tabla nueva: os_concept_mapping no puede conservar los 15 tipos finos.
CREATE TABLE IF NOT EXISTS os_catalog_relation (
    id BIGSERIAL PRIMARY KEY,
    source_item_id INT NOT NULL REFERENCES os_catalog_item(id) ON DELETE CASCADE,
    target_item_id INT NOT NULL REFERENCES os_catalog_item(id) ON DELETE CASCADE,
    relation_type VARCHAR(60) NOT NULL CHECK (relation_type IN (
        'alternate_benefit',
        'billed_in_conjunction_with',
        'concurrent_to',
        'denied_as_integral',
        'frequency_limitations',
        'integral_to',
        'interchangeable_with',
        'not_paid_separately',
        'not_to_be_used_with',
        'paid_as_code',
        'procedure_code_not_used_for',
        'refer_to_details',
        'referencia_literal',
        'shares_frequency_limitation_with',
        'used_in_combination_with'
    )),
    source_system_code VARCHAR(30) NOT NULL DEFAULT 'CDT-2025',
    source_field VARCHAR(30) NOT NULL CHECK (source_field IN ('description', 'procedure', 'notes', 'req')),
    source_value VARCHAR(20) NOT NULL,
    context_text TEXT,
    source_cdt_id INT,
    review_status VARCHAR(20) NOT NULL DEFAULT 'reviewed'
        CHECK (review_status IN ('draft', 'reviewed', 'approved', 'deprecated')),
    provenance TEXT NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_os_catalog_relation_not_self CHECK (source_item_id <> target_item_id),
    -- El contexto diferencia filas que comparten los demás campos (18 grupos en
    -- la fuente), por eso integra la clave única y el ON CONFLICT.
    CONSTRAINT uq_os_catalog_relation UNIQUE
        (source_item_id, target_item_id, relation_type, source_system_code,
         source_field, source_value, context_text)
);

CREATE INDEX IF NOT EXISTS idx_os_catalog_relation_source
    ON os_catalog_relation (source_item_id);
CREATE INDEX IF NOT EXISTS idx_os_catalog_relation_target
    ON os_catalog_relation (target_item_id);
CREATE INDEX IF NOT EXISTS idx_os_catalog_relation_type
    ON os_catalog_relation (relation_type);

COMMENT ON TABLE os_catalog_relation IS
    'Relaciones literales entre ítems del catálogo. Conserva tipo fino, campo y contexto de la fuente; no las aplana a related.';
COMMENT ON COLUMN os_catalog_relation.source_cdt_id IS
    'id de la fila CDT de origen en Argentina_dental_cdt_codes_2025_postgres.corregido.sql.';

-- 4. Identificadores CDT-2025 y mapeos editoriales derivados del CSV auditado.
CREATE TEMP TABLE _dentar_cdt_identifier_import (
    dnt VARCHAR(20) NOT NULL,
    cdt VARCHAR(10) NOT NULL,
    termino TEXT NOT NULL
) ON COMMIT DROP;


DO $$
DECLARE
    v_missing INT;
BEGIN
    SELECT count(*) INTO v_missing
      FROM _dentar_cdt_identifier_import s
      LEFT JOIN os_catalog_item i ON i.permanent_code = s.dnt
     WHERE i.id IS NULL;

    IF v_missing > 0 THEN
        RAISE EXCEPTION 'Faltan % ítems DENTAR-PR para los identificadores CDT.', v_missing;
    END IF;
END $$;

SELECT i.id, 'CDT-2025', s.cdt, FALSE
  FROM _dentar_cdt_identifier_import s
  JOIN os_catalog_item i ON i.permanent_code = s.dnt
  JOIN os_catalog c ON c.id = i.catalog_id AND c.code = 'dentar-pr'
ON CONFLICT (item_id, system_name, value) DO UPDATE SET is_primary = EXCLUDED.is_primary;

SELECT cv.id, 'CDT-2025', s.cdt, s.termino, 'equivalent'
  FROM _dentar_cdt_identifier_import s
  JOIN dentar_concept c ON c.code = s.dnt
  JOIN dentar_concept_version cv ON cv.concept_id = c.id AND cv.version_number = 1
ON CONFLICT (concept_version_id, system_code, external_code) DO UPDATE
   SET external_display = EXCLUDED.external_display,
       relationship = EXCLUDED.relationship;

     mapping_type, relationship_role, review_status)
SELECT i.id, ts.id, s.cdt, s.termino, 'equivalent', 'procedure_concept', 'approved'
  FROM _dentar_cdt_identifier_import s
  JOIN os_catalog_item i ON i.permanent_code = s.dnt
  JOIN os_terminology_system ts ON ts.code = 'CDT-2025'
ON CONFLICT (item_id, terminology_system_id, external_code, relationship_role) DO UPDATE
   SET external_display = EXCLUDED.external_display,
       review_status = EXCLUDED.review_status;

