DO $$
DECLARE
    v_missing INT;
BEGIN
    SELECT count(*) INTO v_missing
      FROM _dentar_cdt_relation_import r
      LEFT JOIN os_catalog_item si ON si.permanent_code = r.source_dnt
      LEFT JOIN os_catalog_item ti ON ti.permanent_code = r.target_dnt
     WHERE si.id IS NULL OR ti.id IS NULL;

    IF v_missing > 0 THEN
        RAISE EXCEPTION 'Faltan % extremos DENTAR-PR para las relaciones CDT.', v_missing;
    END IF;
END $$;

     source_field, source_value, context_text, source_cdt_id,
     review_status, provenance)
SELECT si.id, ti.id, r.relation_type, 'CDT-2025',
       r.source_field, r.source_cdt, r.context_text, r.source_cdt_id,
       'reviewed',
       'Argentina_dental_cdt_codes_2025_postgres.corregido.sql; fila ' || r.source_cdt_id::text
  FROM _dentar_cdt_relation_import r
  JOIN os_catalog_item si ON si.permanent_code = r.source_dnt
  JOIN os_catalog_item ti ON ti.permanent_code = r.target_dnt
  JOIN os_catalog sc ON sc.id = si.catalog_id AND sc.code = 'dentar-pr'
  JOIN os_catalog tc ON tc.id = ti.catalog_id AND tc.code = 'dentar-pr'
ON CONFLICT (source_item_id, target_item_id, relation_type,
             source_system_code, source_field, source_value, context_text)
DO UPDATE
   SET source_cdt_id = EXCLUDED.source_cdt_id,
       review_status = EXCLUDED.review_status,
       provenance = EXCLUDED.provenance;

COMMIT;

